<?php
declare(strict_types=1);
require_once __DIR__ . '/../bootstrap/app.php';require_role('ADMIN');$rows=db_all("SELECT mp.MembershipPlanID,mp.Name,mp.Description,mp.DurationMonths,mp.Price,mp.Currency,mp.ClassLimit,mp.IsActive,(SELECT COUNT(DISTINCT ms.MemberID) FROM MEMBERSHIP ms WHERE ms.MembershipPlanID=mp.MembershipPlanID AND ms.Status='ACTIVE' AND ms.StartsOn<=CURDATE() AND ms.EndsOn>=CURDATE()) ActiveMemberships FROM MEMBERSHIP_PLAN mp ORDER BY mp.IsActive DESC,mp.Price,mp.Name");$pageTitle='Membership plans';$pageSubtitle='Plan catalog and utilization';include V2_ROOT.'/includes/header.php';?>
<div class="table-wrap"><table><thead><tr><th>Plan</th><th>Duration</th><th>Price</th><th>Class limit</th><th>Active members</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=e($row['Name'])?></strong><br><small><?=e($row['Description']??'')?></small></td><td><?=(int)$row['DurationMonths']?> month(s)</td><td><?=e($row['Currency'])?> <?=e(number_format((float)$row['Price'],2))?></td><td><?=$row['ClassLimit']===null?'Unlimited':(int)$row['ClassLimit']?></td><td><?=(int)$row['ActiveMemberships']?></td><td><?=$row['IsActive']?'ACTIVE':'INACTIVE'?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">No plans configured.</td></tr><?php endif;?></tbody></table></div><?php include V2_ROOT.'/includes/footer.php';?>
